UPDATE  SET delivery_state=CASE WHEN attempts >= #{maxAttempts} THEN 'DEAD' ELSE 'READY' END,
    available_at=clock_timestamp()+(#{delayMs} * interval '1 millisecond'),last_error=#{errorType}
WHERE event_id=#{eventId} AND fence=#{fence} AND delivery_state='SENDING' AND available_at > clock_timestamp()
